    String sqlState(Throwable t){for(Throwable c=t;c!=null;c=c.getCause())if(c instanceof SQLException sql&&sql.getSQLState()!=null)return sql.getSQLState();return null;}
    void rejected(String state,Runnable work){assertEquals(state,sqlState(assertThrows(RuntimeException.class,work::run)));}
    List<String> race(Callable<String> work)throws Exception{var barrier=new CyclicBarrier(2);var pool=Executors.newFixedThreadPool(2);Callable<String> gated=()->{barrier.await(10,TimeUnit.SECONDS);return work.call();};try{var a=pool.submit(gated);var b=pool.submit(gated);return List.of(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS));}finally{pool.shutdownNow();}}

    @Test void v29AddsOnlyEmptyInfrastructureAndPreservesRegistration(){Fixture f=fixture();databaseGuard();assertEquals("V29__crew_start_foundation.sql",jdbc.queryForObject("SELECT script FROM flyway_schema_history WHERE version='29'",String.class));var r=tx().execute(s->store.registration(f.registration(),false));assertNull(r.currentRunId());assertNull(r.startedAt());assertEquals(0,r.deviceGeneration());assertEquals(0,count("race_run",f.registration()));assertEquals(0,count("race_start_code",f.registration()));}
    @Test void deferredGraphAcceptsUnstartedRegistrationAtCommitAndRollsBackInvalidGraph(){
        // No SET CONSTRAINTS IMMEDIATE: these checks must execute through the real transaction commit.
        Fixture valid=fixture();
        tx().executeWithoutResult(s->{assertTrue(store.touchRegistration(valid.registration(),0,now()));});
        var saved=tx().execute(s->store.registration(valid.registration(),false));
        assertEquals(1,saved.version());assertNull(saved.startedAt());assertNull(saved.currentRunId());
        var rolledBack=new java.util.concurrent.atomic.AtomicReference<Fixture>();
        rejected("23514",()->tx().executeWithoutResult(s->{
            Fixture invalid=fixture();rolledBack.set(invalid);
            store.insertRun(new Run(UUID.randomUUID(),invalid.registration(),invalid.event(),1,"RUNNING",1,now(),null,null,0));
        }));
        assertNotNull(rolledBack.get());
        assertEquals(0L,jdbc.queryForObject("SELECT count(*) FROM crew_registration WHERE id=?",Long.class,rolledBack.get().registration()));
        assertEquals(0L,jdbc.queryForObject("SELECT count(*) FROM race_event WHERE id=?",Long.class,rolledBack.get().event()));
        assertEquals(0L,jdbc.queryForObject("SELECT count(*) FROM user_account WHERE id=?",Long.class,rolledBack.get().account()));
        assertEquals(1,tx().execute(s->store.registration(valid.registration(),false)).version());
    }
    @Test void plainCodesRoundTripAndAreScopedAndBounded(){Fixture f=fixture(),other=fixture();Code c=tx().execute(s->{Code first=pair(f,"ABC123");pair(other,"ABC123");return first;});tx().executeWithoutResult(s->{assertEquals(c.value(),store.availableCode(f.registration(),"ABC123").value());assertNull(store.availableCode(f.registration(),"abc123"));assertTrue(store.codeValueExists(f.registration(),"ABC123"));assertEquals(2,store.codes(f.registration(),0,2).size());assertEquals(3,store.nextCodeGeneration(f.registration()));});assertEquals("ABC123",jdbc.queryForObject("SELECT code FROM race_start_code WHERE id=?",String.class,c.id()));assertEquals("character varying",jdbc.queryForObject("SELECT data_type FROM information_schema.columns WHERE table_schema=? AND table_name='race_start_code' AND column_name='code'",String.class,SCHEMA));}
