    @Test void pairReceiptIsUniqueImmutableAndSurvivesReplayWindow(){Fixture f=fixture();Command cmd=tx().execute(s->{Code c=pair(f,"ABC123");Code second=store.availableCode(f.registration(),"PAIR02");Command receipt=new Command(UUID.randomUUID(),f.registration(),f.account(),UUID.randomUUID(),"ORIGINAL_ISSUE",1,"a".repeat(64),c.id(),second.id(),null,now(),201,"{}");store.insertCommand(receipt);return receipt;});clock.advance(Duration.ofDays(2));Command loaded=tx().execute(s->store.command(f.account(),cmd.key()));assertEquals(cmd.codeId(),loaded.codeId());assertEquals(cmd.secondCodeId(),loaded.secondCodeId());rejected("23505",()->tx().executeWithoutResult(s->store.insertCommand(new Command(UUID.randomUUID(),f.registration(),f.account(),UUID.randomUUID(),"ORIGINAL_ISSUE",1,"b".repeat(64),cmd.codeId(),cmd.secondCodeId(),null,now(),201,"{}"))));rejected("23514",()->tx().executeWithoutResult(s->store.insertCommand(command(f,UUID.randomUUID(),"ORIGINAL_REGENERATE",cmd.codeId(),null))));rejected("23514",()->jdbc.update("DELETE FROM race_start_command WHERE id=?",cmd.id()));rejected("23514",()->jdbc.update("UPDATE race_start_command SET result='{}'::jsonb WHERE id=?",cmd.id()));}
