    record RaceSetup(Fixture fixture,cz.mh.rallye.rallye_backend.identity.application.AuthService.Principal captain,cz.mh.rallye.rallye_backend.identity.application.AuthService.Principal admin,cz.mh.rallye.rallye_backend.participation.application.StartCodeService.IssuedCodePair pair){}
    RaceSetup raceSetup(boolean running){Fixture f=fixture();var captain=principal(f,false);var admin=principal(fixture(),true);var pair=adminCodes.originals(admin,f.event(),f.registration(),UUID.randomUUID(),0);if(running)lifecycle.command(admin,f.event(),UUID.randomUUID(),0,"STARTED",null);return new RaceSetup(f,captain,admin,pair);}
    cz.mh.rallye.rallye_backend.participation.application.CrewStartService.RedemptionReceipt redeem(RaceSetup r,int original,long version,UUID key,String token){return crewStart.redeem(r.captain(),r.fixture().event(),r.fixture().registration(),key,version,r.pair().codes().get(original).code(),token,null);}
    @Test void realStartByEitherOriginalHasEvaluatorProgressAndOneDevice(){for(int selected:List.of(0,1)){
        var r=raceSetup(true);Fixture f=r.fixture();String token=tokens.create();var receipt=redeem(r,selected,1,UUID.randomUUID(),token);assertEquals("START",receipt.effect());assertEquals(2,receipt.registrationVersion());assertEquals(1,receipt.deviceGeneration());assertEquals(1,count("race_run",f.registration()));assertEquals(1,count("race_device_authorization",f.registration()));
        tx().executeWithoutResult(s->{var reg=store.registration(f.registration(),false);assertEquals(now(),reg.startedAt());assertEquals(receipt.runId(),reg.currentRunId());assertEquals("ACTIVE",store.progress(receipt.runId()).getFirst().status());assertEquals(now(),store.progress(receipt.runId()).getFirst().activatedAt());assertNotNull(store.availableCode(f.registration(),r.pair().codes().get(1-selected).code()));assertEquals(receipt.deviceId(),deviceAccess.require(token,f.registration(),receipt.runId(),1,1).deviceId());});
        assertEquals(f.account(),jdbc.queryForObject("SELECT historical_captain_account_id FROM crew_registration WHERE id=?",UUID.class,f.registration()));assertEquals("Captain",jdbc.queryForObject("SELECT started_members_text FROM crew_registration WHERE id=?",String.class,f.registration()));
    }}
    @Test void realSecondOriginalTakeoverPreservesRunStartProgressAndPointsAtSameInstant(){var r=raceSetup(true);Fixture f=r.fixture();String firstToken=tokens.create();var first=redeem(r,0,1,UUID.randomUUID(),firstToken);var before=tx().execute(s->store.progress(first.runId()));String nextToken=tokens.create();var next=redeem(r,1,2,UUID.randomUUID(),nextToken);assertEquals("TAKEOVER",next.effect());assertEquals(first.runId(),next.runId());assertEquals(first.individualStartedAt(),next.individualStartedAt());assertEquals(first.runVersion(),next.runVersion());assertEquals(1,count("race_run",f.registration()));assertEquals(2,count("race_device_authorization",f.registration()));
        tx().executeWithoutResult(s->{assertEquals(before,store.progress(first.runId()));assertNull(store.activeDevice(secrets.deviceHash(firstToken)));assertEquals(next.deviceId(),deviceAccess.require(nextToken,f.registration(),first.runId(),1,2).deviceId());assertTrue(store.adjustments(f.registration()).isEmpty());});assertEquals("RACE_DEVICE_INVALID",authFailure(()->tx().execute(s->deviceAccess.require(firstToken,f.registration(),first.runId(),1,1))));
    }
