        var r=raceSetup(true);Fixture f=r.fixture();var first=redeem(r,0,1,UUID.randomUUID(),tokens.create());var issued=adminCodes.replacement(r.admin(),f.event(),f.registration(),UUID.randomUUID(),2,points,null);assertTrue(tx().execute(s->store.adjustments(f.registration())).isEmpty());UUID key=UUID.randomUUID();String token=tokens.create();var receipt=crewStart.redeem(r.captain(),f.event(),f.registration(),key,3,issued.code().code(),token,null);assertEquals(Long.toString(points),receipt.pointsAdjustment());assertEquals(points==0?0:1,receipt.runVersion());assertEquals(first.runId(),receipt.runId());assertEquals(receipt,crewStart.redeem(r.captain(),f.event(),f.registration(),key,3,issued.code().code(),token,null));assertEquals(points,tx().execute(s->store.adjustments(f.registration())).stream().mapToLong(Adjustment::points).sum());assertEquals(points==0?0:1,count("race_points_adjustment",f.registration()));assertEquals("START_CODE_INVALID",authFailure(()->crewStart.redeem(r.captain(),f.event(),f.registration(),UUID.randomUUID(),4,issued.code().code(),tokens.create(),null)));
