    @Test void deviceAuthorizationAndRevocationRetainOneTransactionOrder()throws Exception{
        var r=raceSetup(true);Fixture f=r.fixture();String token=tokens.create();var first=redeem(r,0,1,UUID.randomUUID(),token);var authorized=new CountDownLatch(1);var release=new CountDownLatch(1);var revokeEntered=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);
        try{var effect=pool.submit(()->tx().execute(s->{var access=deviceAccess.require(token,f.registration(),first.runId(),1,1);authorized.countDown();try{assertTrue(release.await(15,TimeUnit.SECONDS));}catch(InterruptedException failure){Thread.currentThread().interrupt();throw new IllegalStateException(failure);}assertTrue(store.touchRun(f.registration(),first.runId(),access.runVersion()));return true;}));assertTrue(authorized.await(15,TimeUnit.SECONDS));var revoke=pool.submit(()->{revokeEntered.countDown();return crewStart.revoke(r.admin(),f.event(),f.registration(),first.deviceId(),UUID.randomUUID(),2,1,null);});assertTrue(revokeEntered.await(15,TimeUnit.SECONDS));release.countDown();assertTrue(effect.get(30,TimeUnit.SECONDS));assertEquals("REVOKED",revoke.get(30,TimeUnit.SECONDS).state());assertEquals(1,tx().execute(s->store.run(f.registration(),first.runId(),false)).version());assertEquals("RACE_DEVICE_INVALID",authFailure(()->tx().execute(s->deviceAccess.require(token,f.registration(),first.runId(),1,1))));}
        finally{release.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(15,TimeUnit.SECONDS));}
    }

